-- Запустить один раз в phpMyAdmin в выбранной базе.
-- Категории уже созданы на предыдущем шаге.
INSERT INTO rooms (category_id, room_number, name, price, description, image, is_active)
SELECT c.id, x.room_number, x.name, x.price, x.description, x.image, 1
FROM (
 SELECT 'S-101' room_number,'Стандартный номер №101' name,3000 price,'Полный санузел;Двуспальная кровать;Телевизор' description,'standart.jpg' image, 'Стандартный' category_name
 UNION ALL SELECT 'S-102','Стандартный номер №102',3800,'Полный санузел;Двуспальная кровать;Телевизор','Станд_Кинг_1-1620x1080.jpg','Стандартный'
 UNION ALL SELECT 'S-103','Стандартный номер №103',3400,'Полный санузел;Двуспальная кровать;Телевизор','10.jpg','Стандартный'
 UNION ALL SELECT 'ST-201','Номер-студия №201',4600,'Кухонный уголок;Полный санузел;Двуспальная кровать;Телевизор;Холодильник','487d7588b2bc7b4066334ea328e7a7bb.jpg','Студия'
 UNION ALL SELECT 'ST-202','Номер-студия №202',6200,'Кухонный уголок;Полный санузел;Двуспальная кровать;Телевизор;Холодильник','ee3d8d71bcbd5f9531616f975035f0e9.jpg','Студия'
 UNION ALL SELECT 'ST-203','Номер-студия №203',5400,'Кухонный уголок;Полный санузел;Двуспальная кровать;Телевизор;Холодильник','Vert-16.jpg','Студия'
 UNION ALL SELECT 'L-301','Люкс №301',8500,'Двухкомнатный;Полный санузел;Двуспальная кровать;Телевизор;Холодильник;Кондиционер','Люкс 1.jpg','Люкс'
 UNION ALL SELECT 'L-302','Люкс №302',15000,'Двухкомнатный;Полный санузел;Двуспальная кровать;Телевизор;Холодильник;Кондиционер','garden-ring-hotel-moscow-suit-room-01.jpg','Люкс'
 UNION ALL SELECT 'L-303','Люкс №303',12000,'Двухкомнатный;Полный санузел;Двуспальная кровать;Телевизор;Холодильник;Кондиционер','ren_037_ren03663_hd.jpg','Люкс'
) AS x
JOIN categories c ON c.name=x.category_name
WHERE NOT EXISTS (SELECT 1 FROM rooms r WHERE r.room_number=x.room_number);
